class Session {
  static open = 0;

  constructor(user) {
    this.user = user;
    Session.open += 1;
  }

  [Symbol.dispose]() {
    Session.open -= 1;
    console.log("bye " + this.user);
  }
}

function greeter(user) {
  using session = new Session(user);
  return () => `hi ${session.user}, open: ${Session.open}`;
}

const greet = greeter("Ada");
console.log(greet());

